use crate::{msjc16 as m,catalog,model::*,rules::*,unit_support::*};
use crate::jc029_tests::{pass_top,envelope};
fn setup()->Game{let mut g=game();g.players[0].society_zone.card=Some(g.make_card(m::ID,0));fund(&mut g,0,"JC096",6);g}
fn grave(g:&mut Game,id:&str,seat:usize)->String{let c=g.make_card(id,seat);let id=c.id.clone();g.players[seat].graveyard.push(c);id}
fn action(g:&Game,key:&str,target:Option<String>)->Action{Action{card_id:Some(g.players[0].society_zone.card.as_ref().unwrap().id.clone()),ability_id:Some(key.into()),region:if key==m::REVIVE{Some(0)}else{None},target_id:target,..Action::new("activate")}}
fn ready()->(Game,String,Vec<String>){let mut g=setup();let target=grave(&mut g,"JC044",0);let ids=(0..7).map(|_|grave(&mut g,"JC125",0)).collect();(g,target,ids)}
fn bad(base:&Game,g:&Game){assert!(Game::from_persisted(&serde_json::to_string(g).unwrap()).is_err());let mut r=envelope(base);r.game=g.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn msjc16_original_black_five_closed_and_death_construction(){let s=crate::society::definition(m::ID).unwrap();assert_eq!((s.card.color.as_str(),s.starting_hand,s.subtitle.as_str()),("黑",5,"葬仪主祭"));assert!(!s.card.supported);for c in &catalog::catalog().cards{assert_eq!(crate::society::validate_construction(s,&[catalog::DeckEntry{card_id:c.id.clone(),count:1}],&catalog::catalog().cards).is_ok(),matches!(c.color.as_str(),"黑"|"中立")||c.magic_icon==MagicIcon::Death);}validate_definitions(definitions()).unwrap();assert_eq!(serde_json::to_value(&m::definition().abilities[1].costs).unwrap(),serde_json::json!([{"Assets":3},"ExhaustSource"]));}
#[test]fn msjc16_mill_three_assets_exhaust_no_draw_and_empty_boundary(){for count in [0,1,3]{let mut g=setup();deck_cards(&mut g,0,&vec!["JC125";count]);let h=g.players[0].hand.len();let old=g.players[0].graveyard.len();let a=action(&g,m::MILL,None);act(&mut g,0,a);assert_eq!(g.players[0].assets.iter().filter(|c|c.exhausted).count(),3);assert!(g.players[0].society_zone.card.as_ref().unwrap().exhausted);pass_top(&mut g);assert_eq!(g.players[0].graveyard.len(),old+usize::from(count>0));assert_eq!(g.players[0].hand.len(),h);assert!(!g.players[0].eliminated);restore(&mut g);}}
#[test]fn msjc16_seven_choice_unpaid_then_real_seals_before_response_and_entry(){let(mut g,target,ids)=ready();let a=action(&g,m::REVIVE,Some(target.clone()));act(&mut g,0,a);assert!(g.stack.is_empty());assert_eq!(g.pending.as_ref().unwrap().choice.options.len(),8);assert!(!g.players[0].society_zone.card.as_ref().unwrap().exhausted);assert!(g.players[0].assets.iter().all(|c|!c.exhausted));choose(&mut g,ids);assert_eq!(g.sealed_cards.len(),7);assert_eq!(g.players[0].graveyard.len(),1);assert_eq!(g.players[0].assets.iter().filter(|c|c.exhausted).count(),6);assert!(g.players[0].society_zone.card.as_ref().unwrap().exhausted);restore(&mut g);pass_top(&mut g);assert!(g.players[0].graveyard.is_empty());let c=g.regions[0].cards.iter().find(|c|c.definition=="JC044").unwrap();assert_ne!(c.id,target);assert!(!c.face_down);restore(&mut g);}
#[test]fn msjc16_overlapping_target_is_paid_sealed_and_cannot_revive_from_seal(){let(mut g,target,mut ids)=ready();ids[0]=target.clone();let mut a=action(&g,m::REVIVE,Some(target.clone()));a.cost_selected=Some(ids);act(&mut g,0,a);assert_eq!(g.sealed_cards.len(),7);assert!(!g.players[0].graveyard.iter().any(|c|c.id==target));pass_top(&mut g);assert!(!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="JC044"));assert_eq!(g.sealed_cards.len(),7);assert!(g.players[0].assets.iter().all(|c|c.exhausted));restore(&mut g);}
#[test]fn msjc16_wrong_count_duplicate_foreign_and_non_death_reject_atomically(){for n in 0..5{let(mut g,target,mut ids)=ready();let mut a=action(&g,m::REVIVE,Some(target));match n{0=>{ids.pop();},1=>ids[1]=ids[0].clone(),2=>ids[1]=grave(&mut g,"JC125",1),3=>a.target_id=Some(ids[0].clone()),_=>a.region=Some(999)}a.cost_selected=Some(ids);reject(&mut g,0,a);assert!(g.sealed_cards.is_empty());assert!(g.players[0].assets.iter().all(|c|!c.exhausted));}}
#[test]fn msjc16_response_target_move_or_region_replacement_no_refund(){for region in [false,true]{let(mut g,target,ids)=ready();let mut a=action(&g,m::REVIVE,Some(target.clone()));a.cost_selected=Some(ids);act(&mut g,0,a);if region{let replacement=g.make_card("JC126",0);g.regions[0].card=replacement;}else{let i=g.players[0].graveyard.iter().position(|c|c.id==target).unwrap();let c=g.players[0].graveyard.remove(i);let c=g.fresh(c);g.players[0].hand.push(c);}pass_top(&mut g);assert!(!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="JC044"));assert_eq!(g.sealed_cards.len(),7);assert!(g.players[0].society_zone.card.as_ref().unwrap().exhausted);restore(&mut g);}}
#[test]fn msjc16_corrupt_payment_draft_frames_and_seven_receipts_rejected(){let(mut g,target,ids)=ready();let a=action(&g,m::REVIVE,Some(target));act(&mut g,0,a);for n in 0..4{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.choice.min=Some(6),1=>p.seat=1,2=>p.choice.options[0].id="i999999".into(),_=>if let ChoiceResolution::MSJC16Payment{draft}=&mut p.resolution{draft.targets[0].spec.predicate=None}}bad(&g,&x);}choose(&mut g,ids);for n in 0..6{let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.already_paid.clear(),1=>f.source.card.definition="MSJC07".into(),2=>f.targets[0].spec.predicate=None,3=>f.targets[1].region_instance=None,4=>if let PaidCost::MSJC16Sealed(cards)=&mut f.already_paid[2]{cards[1]=cards[0].clone()},_=>f.steps[0].op=Op::MSJC16Mill}bad(&g,&x);}}
#[test]fn msjc16_first_preparation_optional_once_and_restore(){for accept in [false,true]{let mut g=setup();deck_cards(&mut g,0,&["JC125","JC125","JC125","JC125"]);g.jc035_preparation=None;g.begin_window(Window::Prepare);g.drive().unwrap();restore(&mut g);let mut count=0;for _ in 0..32{if let Some(p)=&g.pending{if p.choice.kind=="jc035-preparation-order"{count+=1;let id=p.choice.options[0].id.clone();choose(&mut g,if accept{vec![id]}else{vec![]});}else if p.choice.kind=="trigger"{choose(&mut g,if accept{vec!["accept".into()]}else{vec![]});}else{panic!("unexpected {}",p.choice.kind)}}else if !g.stack.is_empty(){pass_top(&mut g);}else{break;}}assert_eq!(count,1);assert_eq!(g.players[0].graveyard.len(),if accept{3}else{0});g.turn=2;g.jc035_preparation=None;g.begin_window(Window::Prepare);g.drive().unwrap();assert!(g.pending.is_none()&&g.stack.is_empty());restore(&mut g);}}
fn trace_value(t:crate::abi112_review_play_tests::Trace)->serde_json::Value{let mut v=t.value();for step in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(step["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(step["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(step["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,step["expected"]["state"]);step["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn finish(t:&mut crate::abi112_review_play_tests::Trace){for _ in 0..64{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){return;}else{t.pass();}}panic!("unfinished prepared chain");}
#[test]fn msjc16_natural_first_prepare_mill_seven_seal_revive_and_prepared_export(){use crate::{deck,abi112_review_play_tests::Trace};let mut cases=vec![];
 for overlap in [false,true]{let(g,target,mut ids)=ready();if overlap{ids[0]=target.clone();}let a=action(&g,m::REVIVE,Some(target));let mut t=Trace::new_preserving_rng(g,format!("msjc16-prepared-{}",if overlap{"overlap"}else{"revive"}),710+usize::from(overlap));t.action(0,a);t.choose(ids);finish(&mut t);cases.push(trace_value(t));}
 let mut deck=deck::preset("watchers").unwrap();deck.id="closed-msjc16".into();deck.name="颂亡者自然验证".into();deck.description="非官方预组".into();deck.society_id=Some(m::ID.into());deck.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:47},catalog::DeckEntry{card_id:"JC044".into(),count:3}];assert!(deck::validate(deck.clone()).is_err());let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==m::ID).unwrap().card.supported=true;let deck=deck::validate_with_registry(deck,&catalog::catalog().cards,&societies).unwrap();let mut other=deck.clone();other.society_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();
 let(seed,g)=(1..513).find_map(|seed|{let mut g=Game::new("msjc16-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![deck.clone(),other.clone(),other.clone(),other.clone()]).unwrap();g.drive().unwrap();g.players[0].deck.iter().take(3).any(|c|c.definition=="JC044").then_some((seed,g))}).expect("bounded real initial mill target");
 let mut t=Trace::new_preserving_rng(g,"msjc16-natural-first-prepare-mill-seven-revive".into(),712);let mut invoked=false;let mut done=false;let mut mills=0;
 for _ in 0..2200{if invoked&&t.room.game.pending.is_none()&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){done=true;break;}if let Some(p)=t.room.game.pending.clone(){if p.choice.kind=="investigation"{let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});}else if p.choice.kind=="msjc16-seven"{let ids=p.choice.options.iter().filter(|o|t.room.game.players[0].graveyard.iter().find(|c|c.id==o.id).is_some_and(|c|c.definition!="JC044")).take(7).map(|o|o.id.clone()).collect::<Vec<_>>();assert_eq!(ids.len(),7);t.choose(ids);}else if p.choice.kind=="jc035-preparation-order"{t.choose(vec![p.choice.options[0].id.clone()]);}else if p.choice.kind=="trigger"{t.choose(vec!["accept".into()]);}else{t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}continue;}
 let g=&t.room.game;let legal=g.legal_actions(0);let asset=legal.iter().find(|a|a.action.kind=="asset"&&g.players[0].assets.len()<6);let revive=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(m::REVIVE)&&g.players[0].graveyard.iter().filter(|c|c.definition!="JC044").count()>=7);let mill=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(m::MILL));if let Some(a)=asset.or(revive).or(mill){let a=a.action.clone();if a.ability_id.as_deref()==Some(m::REVIVE){invoked=true;}if a.ability_id.as_deref()==Some(m::MILL){mills+=1;}t.action(0,a);}else{t.pass();}}
 assert!(done,"natural chain unfinished turn {}",t.room.game.turn);assert!(mills>=5);assert_eq!(t.room.game.sealed_cards.len(),7);assert!(t.room.game.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="JC044"));let mut v=trace_value(t);v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true,"paidMillActions":mills});cases.push(v);
 let mut bindings=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(name,bytes)in[("rust-game/src/msjc16.rs",include_bytes!("msjc16.rs").as_slice()),("rust-game/src/msjc16_tests.rs",include_bytes!("msjc16_tests.rs").as_slice()),("rust-game/src/society.rs",include_bytes!("society.rs").as_slice())]{bindings["files"][name]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}let v=serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":bindings,"cases":cases});if let Ok(p)=std::env::var("MSJC16_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&v).unwrap()).unwrap();}
}
#[test]fn msjc16_missing_first_preparation_observation_and_transplanted_trigger_reject(){let mut g=setup();g.jc035_preparation=None;g.begin_window(Window::Prepare);g.drive().unwrap();let mut x=g.clone();x.jc035_preparation=None;bad(&g,&x);let a=m::definition().abilities.remove(0);let mut wrong=a.clone();wrong.ops=vec![Op::MSJC16Mill];wrong.event=None;assert!(m::validate_ability(m::ID,&wrong).is_err());assert!(m::validate_ability("MSJC07",&a).is_err());}
#[test]fn msjc16_black_without_death_and_foreign_grave_never_valid_targets(){let(mut g,_,ids)=ready();for (id,seat) in [("JC086",0),("JC044",1),("JC044",2)]{let target=grave(&mut g,id,seat);let mut a=action(&g,m::REVIVE,Some(target));a.cost_selected=Some(ids.clone());reject(&mut g,0,a);}}
